function InventoryRow({item,act,loading}:{item:InventoryItem;act:(b:Record<string,unknown>,s:string)=>Promise<unknown>;loading:boolean}) {
  const [quantity,setQuantity]=useState(item.quantity),[reorderLevel,setReorderLevel]=useState(item.reorderLevel);
  const low=quantity<=reorderLevel;
  return <div className="stock-row"><span><strong>{item.name}</strong><small>{item.unit}</small></span><label>In stock<input type="number" min="0" value={quantity} onChange={event=>setQuantity(Math.max(0,Number(event.target.value)||0))}/></label><label>Low at<input type="number" min="0" value={reorderLevel} onChange={event=>setReorderLevel(Math.max(0,Number(event.target.value)||0))}/></label><span className={`stock-status ${low?"low":"good"}`}>{low?"Low stock":"Stock OK"}</span><div className="stock-actions"><button disabled={loading} onClick={()=>void act({action:"update_inventory",inventoryId:item.id,quantity,reorderLevel},`${item.name} stock updated.`)}>Save</button><button className="danger" disabled={loading} title="Remove item" onClick={()=>{if(confirm(`Remove ${item.name} from stock?`))void act({action:"remove_inventory",inventoryId:item.id},`${item.name} removed from stock.`)}}><Trash2 size={14}/></button></div></div>
}

